41	// Charged on every quote, unconditionally — it is the cost of assessing the
42	// items, not a penalty for being a new customer. Named "first insurance" in
43	// some of the domain material, which misleads: it does not depend on customer
44	// history or on the quote's position in the scenario.
45	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
46	
47	const percentOf = (amount: number, percent: number): number =>
48	  (amount * percent) / 100;
49	
50	const itemBasePremium = (item: Item): number =>
51	  BASE_PREMIUM_BY_TYPE[item.type];
52	
53	const BLOCK_SIZE = 3;
54	
55	const BLOCK_PREMIUM = 60;
56	
57	const sumOf = (amounts: number[]): number =>
58	  amounts.reduce((sum, amount) => sum + amount, 0);
59	
60	const formsABlock = (items: Item[]): boolean => items.length === BLOCK_SIZE;
61	
62	const sumOfItemBasePremiums = (items: Item[]): number =>
63	  sumOf(items.map(itemBasePremium));
64	
65	const groupByType = (items: Item[]): Item[][] => {
66	  const types = new Set(items.map((item) => item.type));
67	
68	  return [...types].map((type) => items.filter((item) => item.type === type));
69	};
70	
71	const alikeGroupBasePremium = (items: Item[]): number =>
72	  formsABlock(items) ? BLOCK_PREMIUM : sumOfItemBasePremiums(items);
73	
74	const policyBasePremium = (items: Item[]): number =>
75	  sumOf(groupByType(items).map(alikeGroupBasePremium));
76	
77	const roundPremiumInMHPCOsFavor = (amount: number): number =>
78	  Math.ceil(amount);
79	
80	// The inputs a single quote is computed from. Today only `items` is consumed;
81	// `customer` is threaded through so policy-wide modifiers that depend on
82	// customer history (loyalty, follow-up contract) have a seat at the table.
83	type QuoteRequest = {
84	  customer: Customer;
85	  items: Item[];
86	};
87	
88	const LOYALTY_YEARS = 2;
89	
90	const LOYALTY_DISCOUNT_PERCENT = -20;
91	
92	const isLoyal = (customer: Customer): boolean =>
93	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
94	
95	// Policy-wide modifiers do NOT compound: each is an independent percentage of
96	// the policy base premium, and they are summed. Chaining them (base * 1.1 * 0.8)
97	// would give a different, wrong answer.
98	const policyModifierPercents = (request: QuoteRequest): number[] => [
99	  INITIAL_ASSESSMENT_SURCHARGE_PERCENT,
100	  ...(isLoyal(request.customer) ? [LOYALTY_DISCOUNT_PERCENT] : []),
101	];
102	
103	const applyPolicyModifiers = (
104	  basePremium: number,
105	  request: QuoteRequest,
106	): number =>
107	  basePremium +
108	  sumOf(
109	    policyModifierPercents(request).map((percent) =>
110	      percentOf(basePremium, percent),
111	    ),
112	  );
113	
114	const CURSE_SURCHARGE_PERCENT = 50;
115	
116	const HIGH_ENCHANTMENT_LEVEL = 5;
117	
118	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
119	
120	const isHighlyEnchanted = (item: Item): boolean =>
121	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
122	
123	const isCursed = (item: Item): boolean => item.cursed === true;
124	
125	type ItemSurchargeRule = {
126	  applies: (item: Item) => boolean;
127	  percent: number;
128	};
129	
130	const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
131	  { applies: isCursed, percent: CURSE_SURCHARGE_PERCENT },
132	  { applies: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
133	];
134	
135	// Item-scoped surcharges are charged on the item's own base premium, so they
136	// must NOT go through applyPolicyModifiers.
137	const itemSurcharges = (item: Item): number =>
138	  sumOf(
139	    ITEM_SURCHARGE_RULES.filter((rule) => rule.applies(item)).map((rule) =>
140	      percentOf(itemBasePremium(item), rule.percent),
141	    ),
142	  );
143	
144	const policyItemSurcharges = (items: Item[]): number =>
145	  sumOf(items.map(itemSurcharges));
146	
147	const quotePremium = (request: QuoteRequest): number =>
148	  roundPremiumInMHPCOsFavor(
149	    applyPolicyModifiers(policyBasePremium(request.items), request) +
150	      policyItemSurcharges(request.items) +
151	      PROCESSING_FEE,
152	  );
153	
154	export const runScenario = (scenario: Scenario): ScenarioResults => ({
155	  results: scenario.steps.map((step) => ({
156	    premium: quotePremium({
157	      customer: scenario.customer,
158	      items: step.items ?? [],
159	    }),
160	  })),
161	});
